// Home bot: Seerr requests, downloads, server status and power, by polling the bot (n8n stays private).
// Only obeys TELEGRAM_CHAT_ID. Service keys come from homepage.secret via $env.
const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const PVE = 'https://192.168.3.200:8006/api2/json/nodes/pve';
const PVE_AUTH = `PVEAPIToken=${$env.HOMELAB_PVE_POWER_TOKEN_ID}=${$env.HOMELAB_PVE_POWER_TOKEN_SECRET}`;
const CONFIRM_SECONDS = 120;
if (!TOKEN || !CHAT) throw new Error('Set HOMELAB_TELEGRAM_BOT_TOKEN and HOMELAB_TELEGRAM_CHAT_ID in docker/n8n/.env');

const helpers = this.helpers;
const s = $getWorkflowStaticData('global');
const tg = (method, body) => helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/${method}`, body, json: true, timeout: 15000 });
const say = (text) => tg('sendMessage', { chat_id: CHAT, text });
const pve = (method, path, form) => helpers.httpRequest({
  method, url: `${PVE}${path}`, headers: { Authorization: PVE_AUTH, ...(form ? { 'Content-Type': 'application/x-www-form-urlencoded' } : {}) },
  body: form, json: true, skipSslCertificateValidation: true, timeout: 15000 });


const LAN = 'http://192.168.3.201';
const seerr = (method, path, opts = {}) => helpers.httpRequest({ method, url: `${LAN}:5055/api/v1${path}`,
  headers: { 'X-Api-Key': $env.HOMEPAGE_VAR_SEERR_KEY || '' }, json: true, timeout: 20000, ...opts });
const STATUS = { 2: '🕓 Requested', 3: '⏳ Downloading/processing', 4: '🟡 Partly in library', 5: '✅ In library' };
const REQ_STATUS = { 1: '🕓 Pending approval', 2: '👍 Approved', 3: '❌ Declined', 4: '⚠️ Failed', 5: '✅ Completed' };
const year = (r) => (r.releaseDate || r.firstAirDate || '').slice(0, 4);
const titleOf = (r) => r.title || r.name || 'Unknown';
const fmtEta = (sec) => sec >= 8640000 || sec < 0 ? '∞' : sec >= 3600 ? `${Math.floor(sec / 3600)} h ${Math.round(sec % 3600 / 60)} min` : `${Math.max(1, Math.round(sec / 60))} min`;

async function search(type, query) {
  if (!query) return say(`Usage: /${type === 'movie' ? 'movie' : 'show'} <title>, e.g. /${type === 'movie' ? 'movie dune' : 'show the bear'}`);
  const r = await seerr('GET', '/search', { qs: { query, page: 1, language: 'en' } });
  const hits = (r.results || []).filter(x => x.mediaType === type).slice(0, 5);
  if (!hits.length) return say(`No ${type === 'movie' ? 'movies' : 'shows'} found for “${query}”.`);
  s.search = { type, hits: hits.map(h => ({ id: h.id, title: titleOf(h), year: year(h), status: h.mediaInfo?.status || 1 })), expires: Date.now() + 10 * 60000 };
  const lines = s.search.hits.map((h, i) => `${i + 1}. ${h.title}${h.year ? ` (${h.year})` : ''}${STATUS[h.status] ? `  ${STATUS[h.status]}` : ''}`);
  return say(`${type === 'movie' ? '🎬' : '📺'} Results for “${query}”:\n${lines.join('\n')}\n\nReply /pick <number> to request.`);
}

async function pick(n) {
  const sr = s.search;
  if (!sr || Date.now() > sr.expires) return say('No recent search. Use /movie <title> or /show <title> first.');
  const h = sr.hits[Number(n) - 1];
  if (!h) return say(`Pick a number from 1 to ${sr.hits.length}.`);
  if (sr.type === 'subs') return subsFor(h);
  if (sr.type === 'delete') return deleteAsk(h);
  if (sr.type?.startsWith('ll-')) return pickBookLL(sr.kind, h);
  if (ARR[sr.type]) return pickArr(sr.type, h);
  if (h.status >= 2) return say(`${h.title} is already ${STATUS[h.status].replace(/^\S+ /, '').toLowerCase()}. Nothing to do.`);
  const body = sr.type === 'movie' ? { mediaType: 'movie', mediaId: h.id } : { mediaType: 'tv', mediaId: h.id, seasons: 'all' };
  await seerr('POST', '/request', { body });
  h.status = 2;
  return say(`✅ Requested ${h.title}${h.year ? ` (${h.year})` : ''}. ${sr.type === 'movie' ? 'Radarr' : 'Sonarr'} will start looking for it now. You'll get a message when it lands in Jellyfin.`);
}

async function recentRequests() {
  const r = await seerr('GET', '/request', { qs: { take: 5, skip: 0, sort: 'added', filter: 'all' } });
  const items = r.results || [];
  if (!items.length) return say('No requests yet.');
  const lines = await Promise.all(items.map(async (q) => {
    let name = `${q.type === 'movie' ? 'Movie' : 'Show'} #${q.media?.tmdbId}`;
    try { const d = await seerr('GET', `/${q.type === 'movie' ? 'movie' : 'tv'}/${q.media?.tmdbId}`); name = titleOf(d); } catch (e) {}
    const st = q.media?.status === 5 ? '✅ In library' : (REQ_STATUS[q.status] || '');
    return `• ${name}  ${st}`;
  }));
  return say(`🙋 Recent requests:\n${lines.join('\n')}`);
}

async function downloads() {
  const cookie = await qbitLogin();
  if (!cookie) return say('Could not log in to qBittorrent. Check QBIT_USER / QBIT_PASS in homepage.secret.');
  const list = await helpers.httpRequest({ url: `${LAN}:8080/api/v2/torrents/info`, qs: { filter: 'downloading', sort: 'progress', reverse: true },
    headers: { Cookie: cookie, Referer: `${LAN}:8080` }, json: true, timeout: 15000 });
  if (!list.length) return say('📥 Nothing downloading right now.');
  const lines = list.slice(0, 8).map(t => `• ${t.name.slice(0, 60)}\n   ${Math.round(t.progress * 100)}% · ${(t.dlspeed / 1e6).toFixed(1)} MB/s · ${fmtEta(t.eta)} left`);
  return say(`📥 Downloading (${list.length}):\n${lines.join('\n')}`);
}

// ---- Lidarr (music) and Bookshelf (ebooks / audiobooks) ----
const ARR = {
  music:     { url: `${LAN}:8686/api/v1`, key: $env.HOMEPAGE_VAR_LIDARR_KEY, app: 'Lidarr', icon: '🎵', lib: 'Jellyfin and Navidrome' },
  ebook:     { url: `${LAN}:8788/api/v1`, key: $env.HOMEPAGE_VAR_BOOKSHELF_EBOOK_KEY, app: 'Bookshelf (ebooks)', icon: '📚', lib: 'Calibre-Web' },
  audiobook: { url: `${LAN}:8787/api/v1`, key: $env.HOMEPAGE_VAR_BOOKSHELF_AUDIO_KEY, app: 'Bookshelf (audio)', icon: '🎧', lib: 'Audiobookshelf' },
};
const arr = (kind, method, path, opts = {}) => helpers.httpRequest({ method, url: `${ARR[kind].url}${path}`,
  headers: { 'X-Api-Key': ARR[kind].key || '' }, json: true, timeout: 90000, ...opts });

async function arrDefaults(kind) {
  const roots = await arr(kind, 'GET', '/rootfolder');
  const root = roots[0];
  if (!root) throw new Error(`no root folder set in ${ARR[kind].app}`);
  let q = root.defaultQualityProfileId, m = root.defaultMetadataProfileId;
  if (!q) q = (await arr(kind, 'GET', '/qualityprofile'))[0]?.id;
  if (!m) m = (await arr(kind, 'GET', '/metadataprofile'))[0]?.id;
  return { rootFolderPath: root.path, qualityProfileId: q, metadataProfileId: m };
}

async function searchArr(kind, query) {
  if (!query) return say(`Usage: /${kind} <name>, e.g. /${kind} ${kind === 'music' ? 'burna boy' : 'atomic habits'}`);
  if (kind === 'music') {
    const r = await arr('music', 'GET', '/artist/lookup', { qs: { term: query } });
    const hits = r.slice(0, 5);
    if (!hits.length) return say(`No artists found for “${query}”.`);
    s.search = { type: 'music', hits, expires: Date.now() + 10 * 60000 };
    const lines = hits.map((a, i) => `${i + 1}. ${a.artistName}${a.genres?.length ? ` (${a.genres.slice(0, 2).join(', ')})` : ''}${a.id ? '  ✅ In library' : ''}`);
    return say(`🎵 Artists for “${query}”:\n${lines.join('\n')}\n\nReply /pick <number> to add the artist (latest album is downloaded).`);
  }
  const r = await arr(kind, 'GET', '/book/lookup', { qs: { term: query } });
  const hits = r.slice(0, 5);
  if (!hits.length) return say(`No books found for “${query}”.`);
  s.search = { type: kind, hits, expires: Date.now() + 10 * 60000 };
  const lines = hits.map((b, i) => {
    const y = (b.releaseDate || '').slice(0, 4);
    return `${i + 1}. ${b.title}${y ? ` (${y})` : ''}${b.author?.authorName ? ` by ${b.author.authorName}` : ''}${b.id ? '  ✅ In library' : ''}`;
  });
  return say(`${ARR[kind].icon} ${kind === 'ebook' ? 'Ebooks' : 'Audiobooks'} for “${query}”:\n${lines.join('\n')}\n\nReply /pick <number> to request.`);
}

async function pickArr(kind, hit) {
  const a = ARR[kind];
  if (hit.id) return say(`That's already in ${a.app}. Nothing to do.`);
  const d = await arrDefaults(kind);
  if (kind === 'music') {
    await arr('music', 'POST', '/artist', { body: { ...hit, ...d, monitored: true,
      addOptions: { monitor: 'latest', searchForMissingAlbums: true } } });
    hit.id = -1;
    return say(`✅ Added ${hit.artistName} to Lidarr. Their latest album is being searched for now and will appear in ${a.lib}.\nOlder albums can be added from Lidarr anytime.`);
  }
  const author = { ...(hit.author || {}), ...d, monitored: false,
    addOptions: { monitor: 'none', searchForMissingBooks: false } };
  await arr(kind, 'POST', '/book', { body: { ...hit, author, monitored: true, addOptions: { searchForNewBook: true } } });
  hit.id = -1;
  return say(`✅ Requested ${hit.title}${hit.author?.authorName ? ` by ${hit.author.authorName}` : ''}. ${a.app} is searching for it now; it will appear in ${a.lib}.`);
}

// ---- LazyLibrarian (ebooks and audiobooks) ----
const LL_TYPE = { ebook: 'eBook', audiobook: 'AudioBook' };
const LL_DEST = { ebook: 'Calibre-Web', audiobook: 'Audiobookshelf' };
const plus = (v) => encodeURIComponent(String(v)).replace(/%20/g, '+');   // LazyLibrarian wants quote_plus style
async function ll(cmd, params = {}) {
  const q = Object.entries({ apikey: $env.HOMEPAGE_VAR_LAZYLIBRARIAN_KEY || '', cmd, ...params }).map(([k, v]) => `${k}=${plus(v)}`).join('&');
  const r = await helpers.httpRequest({ url: `${LAN}:5299/api?${q}`, timeout: 90000, json: false });
  let data = r;
  if (typeof r === 'string') { try { data = JSON.parse(r); } catch (e) { data = r; } }
  if (typeof data === 'string' && /invalid|unknown command|error|missing/i.test(data)) throw new Error(data.slice(0, 200));
  return data;
}
const pickField = (o, names) => { for (const n of names) if (o?.[n] !== undefined && o[n] !== null && o[n] !== '') return o[n]; return undefined; };

async function searchBooksLL(kind, query) {
  if (!query) return say(`Usage: /${kind} <title>, e.g. /${kind} atomic habits`);
  const data = await ll('findBook', { name: query });
  const list = Array.isArray(data) ? data : (data?.results || data?.data || data?.books || []);
  const hits = list.map(b => ({
    id: pickField(b, ['bookid', 'BookID', 'id']),
    title: pickField(b, ['bookname', 'BookName', 'title']) || 'Unknown',
    author: pickField(b, ['authorname', 'AuthorName', 'author']),
    year: String(pickField(b, ['bookdate', 'BookDate', 'date']) || '').slice(0, 4),
  })).filter(h => h.id).slice(0, 5);
  if (!hits.length) return say(`No books found for “${query}”.`);
  s.search = { type: `ll-${kind}`, kind, hits, expires: Date.now() + 10 * 60000 };
  const lines = hits.map((h, i) => `${i + 1}. ${h.title}${/^\d{4}$/.test(h.year) ? ` (${h.year})` : ''}${h.author ? ` by ${h.author}` : ''}`);
  return say(`${kind === 'ebook' ? '📚 Ebooks' : '🎧 Audiobooks'} for “${query}”:\n${lines.join('\n')}\n\nReply /pick <number> to request.`);
}

async function pickBookLL(kind, h) {
  if (h.requested) return say(`${h.title} was already requested.`);
  await ll('addBook', { id: h.id });
  await ll('queueBook', { id: h.id, type: LL_TYPE[kind] });
  await ll('searchBook', { id: h.id, type: LL_TYPE[kind] });
  h.requested = true;
  return say(`✅ Requested the ${kind === 'ebook' ? 'ebook' : 'audiobook'} of ${h.title}${h.author ? ` by ${h.author}` : ''}. LazyLibrarian is searching for it now; it will appear in ${LL_DEST[kind]}.\nBooks can be hard to find on public indexers, so it may take a while (check /downloads).`);
}

// ---- qBittorrent login (shared) ----
async function qbitLogin() {
  const login = await helpers.httpRequest({ method: 'POST', url: `${LAN}:8080/api/v2/auth/login`,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Referer: `${LAN}:8080` },
    body: `username=${encodeURIComponent($env.HOMEPAGE_VAR_QBIT_USER || '')}&password=${encodeURIComponent($env.HOMEPAGE_VAR_QBIT_PASS || '')}`,
    returnFullResponse: true, timeout: 15000 });
  return [].concat(login.headers?.['set-cookie'] || []).map(c => c.split(';')[0]).join('; ');
}
const gb = (b) => b >= 1e9 ? `${(b / 1e9).toFixed(1)} GB` : `${Math.round((b || 0) / 1e6)} MB`;

// ---- Bazarr: subtitles on demand ----
const bazarr = (method, path, qs) => helpers.httpRequest({ method, url: `${LAN}:6767/api${path}`, qs,
  headers: { 'X-API-KEY': $env.HOMEPAGE_VAR_BAZARR_KEY || '' }, json: true, timeout: 60000 });
async function subsSearch(query) {
  if (!query) return say('Usage: /subs <movie or show>, e.g. /subs dune');
  const q = query.toLowerCase();
  const [mv, sr] = await Promise.all([bazarr('GET', '/movies', { start: 0, length: -1 }), bazarr('GET', '/series', { start: 0, length: -1 })]);
  const hits = [
    ...(mv.data || []).filter(x => (x.title || '').toLowerCase().includes(q)).map(x => ({ kind: 'movie', id: x.radarrId, title: x.title, year: x.year })),
    ...(sr.data || []).filter(x => (x.title || '').toLowerCase().includes(q)).map(x => ({ kind: 'series', id: x.sonarrSeriesId, title: x.title, year: x.year })),
  ].slice(0, 6);
  if (!hits.length) return say(`Nothing in Bazarr matches “${query}”. It only knows movies and shows already in your library.`);
  if (hits.length === 1) return subsFor(hits[0]);
  s.search = { type: 'subs', hits, expires: Date.now() + 10 * 60000 };
  return say(`🔤 Which one?\n${hits.map((h, i) => `${i + 1}. ${h.title}${h.year ? ` (${h.year})` : ''} · ${h.kind === 'movie' ? 'movie' : 'show'}`).join('\n')}\n\nReply /pick <number>.`);
}
async function subsFor(h) {
  if (h.kind === 'movie') await bazarr('PATCH', '/movies', { radarrid: h.id, action: 'search-missing' });
  else await bazarr('PATCH', '/series', { seriesid: h.id, action: 'search-missing' });
  return say(`🔤 Searching subtitles for ${h.title}. They're saved next to the video and show up in Jellyfin automatically (usually within a minute or two).`);
}

// ---- Radarr / Sonarr: delete, remove torrents, free space ----
const radarr = (method, path, qs) => helpers.httpRequest({ method, url: `${LAN}:7878/api/v3${path}`, qs,
  headers: { 'X-Api-Key': $env.HOMEPAGE_VAR_RADARR_KEY || '' }, json: true, timeout: 60000 });
const sonarr = (method, path, qs) => helpers.httpRequest({ method, url: `${LAN}:8989/api/v3${path}`, qs,
  headers: { 'X-Api-Key': $env.HOMEPAGE_VAR_SONARR_KEY || '' }, json: true, timeout: 60000 });
async function deleteSearch(query) {
  if (!query) return say('Usage: /delete <movie or show>, e.g. /delete dune');
  const q = query.toLowerCase();
  const [movies, series] = await Promise.all([radarr('GET', '/movie').catch(() => []), sonarr('GET', '/series').catch(() => [])]);
  const hits = [
    ...movies.filter(m => (m.title || '').toLowerCase().includes(q)).map(m => ({ kind: 'movie', id: m.id, title: m.title, year: m.year, size: m.sizeOnDisk || m.movieFile?.size || 0 })),
    ...series.filter(x => (x.title || '').toLowerCase().includes(q)).map(x => ({ kind: 'series', id: x.id, title: x.title, year: x.year, size: x.statistics?.sizeOnDisk || 0 })),
  ].slice(0, 6);
  if (!hits.length) return say(`No movie or show matching “${query}” in Radarr or Sonarr.`);
  s.search = { type: 'delete', hits, expires: Date.now() + 10 * 60000 };
  return say(`🗑️ Which one should be deleted?\n${hits.map((h, i) => `${i + 1}. ${h.title}${h.year ? ` (${h.year})` : ''} · ${h.kind === 'movie' ? 'movie' : 'show'} · ${gb(h.size)}`).join('\n')}\n\nReply /pick <number>. You'll be asked to confirm.`);
}
async function deleteAsk(h) {
  const code = String(Math.floor(1000 + Math.random() * 9000));
  s.pendingDelete = { ...h, code, expires: Date.now() + 120000 };
  return say(`⚠️ Delete ${h.title}${h.year ? ` (${h.year})` : ''} and its files (${gb(h.size)})?\nIts torrent is removed too, then the space is freed on the server. This can't be undone.\n\nReply /confirm ${code} within 2 minutes, or /cancel.`);
}
async function deleteDo(h) {
  let hashes = [];
  try {
    const hist = h.kind === 'movie' ? await radarr('GET', '/history/movie', { movieId: h.id }) : await sonarr('GET', '/history/series', { seriesId: h.id });
    hashes = [...new Set((Array.isArray(hist) ? hist : (hist.records || [])).map(r => r.downloadId).filter(Boolean).map(x => x.toLowerCase()))];
  } catch (e) { /* no history: nothing to remove from qBittorrent */ }
  if (h.kind === 'movie') await radarr('DELETE', `/movie/${h.id}`, { deleteFiles: true, addImportExclusion: false });
  else await sonarr('DELETE', `/series/${h.id}`, { deleteFiles: true, addImportListExclusion: false });
  let torrents = 0;
  if (hashes.length) {
    try {
      const cookie = await qbitLogin();
      if (cookie) {
        await helpers.httpRequest({ method: 'POST', url: `${LAN}:8080/api/v2/torrents/delete`,
          headers: { Cookie: cookie, Referer: `${LAN}:8080`, 'Content-Type': 'application/x-www-form-urlencoded' },
          body: `hashes=${hashes.join('|')}&deleteFiles=true`, timeout: 30000 });
        torrents = hashes.length;
      }
    } catch (e) { await say(`(Couldn't remove the torrent from qBittorrent: ${e.message}. Delete it there by hand so the space is freed.)`); }
  }
  trim = true;
  return say(`✅ Deleted ${h.title} (${gb(h.size)})${torrents ? ` and ${torrents} torrent${torrents > 1 ? 's' : ''}` : ''}.\n🧹 Freeing the space on the server now (pct fstrim 201). It takes a few minutes; tonight's report shows the new storage level.`);
}

// ---- Files sent to the bot, processed by Stirling PDF ----
const MAX_FILE = 20 * 1024 * 1024;   // Telegram bot download limit
s.files = s.files || { docs: [], photos: [] };
const fresh = (a) => (a || []).filter(f => Date.now() - f.t < 15 * 60000);
s.files.docs = fresh(s.files.docs); s.files.photos = fresh(s.files.photos);
function multipart(fields) {
  const boundary = '----homebot' + Math.random().toString(16).slice(2);
  const parts = [];
  for (const f of fields) {
    let head = `--${boundary}\r\nContent-Disposition: form-data; name="${f.name}"`;
    if (f.data) head += `; filename="${f.filename}"\r\nContent-Type: ${f.type || 'application/octet-stream'}`;
    parts.push(Buffer.from(head + '\r\n\r\n'), f.data ? Buffer.from(f.data) : Buffer.from(String(f.value)), Buffer.from('\r\n'));
  }
  parts.push(Buffer.from(`--${boundary}--\r\n`));
  return { body: Buffer.concat(parts), contentType: `multipart/form-data; boundary=${boundary}` };
}
async function tgDownload(fileId) {
  const info = await tg('getFile', { file_id: fileId });
  const r = await helpers.httpRequest({ url: `https://api.telegram.org/file/bot${TOKEN}/${info.result.file_path}`, encoding: 'arraybuffer', timeout: 120000 });
  return Buffer.from(r);
}
async function stirling(path, fields) {
  const mp = multipart(fields);
  const headers = { 'Content-Type': mp.contentType };
  if ($env.HOMEPAGE_VAR_STIRLING_KEY) headers['X-API-KEY'] = $env.HOMEPAGE_VAR_STIRLING_KEY;
  const r = await helpers.httpRequest({ method: 'POST', url: `${LAN}:8095${path}`, body: mp.body, headers, encoding: 'arraybuffer', timeout: 600000 });
  return Buffer.from(r);
}
async function sendDoc(buf, filename, caption) {
  const mp = multipart([{ name: 'chat_id', value: CHAT }, { name: 'caption', value: caption },
                        { name: 'document', filename, data: buf, type: 'application/pdf' }]);
  return helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/sendDocument`, body: mp.body,
    headers: { 'Content-Type': mp.contentType }, timeout: 120000 });
}
const mbs = (n) => `${(n / 1048576).toFixed(1)} MB`;
const pdfFile = (d, data) => ({ name: 'fileInput', filename: d.name, data, type: 'application/pdf' });
async function pdfJob(job) {
  if (job === 'compress' || job === 'ocr') {
    const d = s.files.docs[s.files.docs.length - 1];
    if (!d) return say(`Send me a PDF (as a file) with the caption /${job}, or send the PDF first and then /${job}.`);
    await say(job === 'compress' ? `🗜️ Compressing ${d.name}…` : `🔤 Making ${d.name} searchable (OCR). This can take a few minutes…`);
    const input = await tgDownload(d.id);
    const out = job === 'compress'
      ? await stirling('/api/v1/misc/compress-pdf', [pdfFile(d, input), { name: 'optimizeLevel', value: 5 }])
      : await stirling('/api/v1/misc/ocr-pdf', [pdfFile(d, input), { name: 'languages', value: 'eng' }, { name: 'ocrType', value: 'skip-text' }, { name: 'ocrRenderType', value: 'hocr' }]);
    const base = d.name.replace(/\.pdf$/i, '');
    await sendDoc(out, `${base}-${job === 'compress' ? 'compressed' : 'searchable'}.pdf`,
      job === 'compress' ? `🗜️ ${mbs(input.length)} → ${mbs(out.length)}` : '🔤 Searchable PDF');
    s.files.docs = s.files.docs.filter(x => x.id !== d.id);
    return;
  }
  if (job === 'pdf') {
    const photos = s.files.photos;
    if (!photos.length) return say('Send me one or more photos first (with the caption /pdf, or then send /pdf).');
    await say(`📄 Combining ${photos.length} photo${photos.length > 1 ? 's' : ''} into a PDF…`);
    const imgs = [];
    for (const [i, p] of photos.entries()) imgs.push({ name: 'fileInput', filename: `page-${String(i + 1).padStart(2, '0')}.jpg`, data: await tgDownload(p.id), type: 'image/jpeg' });
    const out = await stirling('/api/v1/convert/img/pdf', [...imgs, { name: 'fitOption', value: 'fitDocumentToImage' }, { name: 'colorType', value: 'color' }, { name: 'autoRotate', value: 'true' }]);
    await sendDoc(out, `photos-${new Date().toISOString().slice(0, 10)}.pdf`, `📄 ${photos.length} page${photos.length > 1 ? 's' : ''}`);
    s.files.photos = [];
    return;
  }
  if (job === 'merge') {
    const docs = s.files.docs;
    if (docs.length < 2) return say('Send me two or more PDFs first, then /merge.');
    await say(`📎 Merging ${docs.length} PDFs…`);
    const files = [];
    for (const d of docs) files.push(pdfFile(d, await tgDownload(d.id)));
    const out = await stirling('/api/v1/general/merge-pdfs', [...files, { name: 'sortType', value: 'orderProvided' }]);
    await sendDoc(out, `merged-${new Date().toISOString().slice(0, 10)}.pdf`, `📎 ${docs.length} PDFs merged`);
    s.files.docs = [];
  }
}

const res = await tg('getUpdates', { offset: s.offset ?? 0, timeout: 0, allowed_updates: ['message'] });
const updates = res.result || [];
if (!updates.length) return [];
const firstRun = s.offset === undefined;
s.offset = updates[updates.length - 1].update_id + 1;
// Confirm these updates to Telegram immediately: an overlapping run (slow searches can outlast the
// 15-second schedule) would otherwise fetch and answer the same messages again.
await tg('getUpdates', { offset: s.offset, timeout: 0, limit: 1 });
if (firstRun) return [{ json: { note: `skipped ${updates.length} old message(s) on first run` } }];   // never act on stale commands

const log = [];
const jobs = [];
let trim = false;
for (const u of updates) {
  const m = u.message;
  if (!m || String(m.chat?.id) !== CHAT) continue;   // only your chat
  // Files for Stirling PDF are remembered for 15 minutes
  const doc = m.document, photo = m.photo;
  if (doc || photo) {
    const f = photo ? photo[photo.length - 1] : doc;
    if ((f.file_size || 0) > MAX_FILE) { await say(`That file is ${mbs(f.file_size)}; Telegram only lets bots download files up to 20 MB.`); continue; }
    const isPdf = doc && (doc.mime_type === 'application/pdf' || /\.pdf$/i.test(doc.file_name || ''));
    const isImg = photo || (doc && /^image\//.test(doc.mime_type || ''));
    if (isPdf) s.files.docs.push({ id: doc.file_id, name: doc.file_name || 'document.pdf', t: Date.now() });
    else if (isImg) s.files.photos.push({ id: f.file_id, t: Date.now() });
    else { await say('I can only work with PDFs and photos.'); continue; }
    if (!m.caption) { log.push('file stored'); continue; }
  }
  const text = (m.text ?? m.caption ?? '').trim();
  if (!text) continue;
  const cmd = text.split(/\s+/)[0].toLowerCase().replace(/@\w+$/, '');
  const rest = text.slice(text.split(/\s+/)[0].length).trim();
  const arg = rest.toLowerCase();
  const now = Date.now();

  if (['/compress', '/ocr', '/pdf', '/merge'].includes(cmd)) { jobs.push(cmd.slice(1)); log.push(cmd); continue; }
  if (cmd === '/subs') { try { await subsSearch(rest); } catch (e) { await say(`Bazarr failed: ${e.message}`); } log.push('subs'); continue; }
  if (cmd === '/delete') { try { await deleteSearch(rest); } catch (e) { await say(`Search failed: ${e.message}`); } log.push('delete search'); continue; }
  if (cmd === '/trim') { trim = true; await say('🧹 Freeing unused space on the server (pct fstrim 201). It takes a few minutes.'); log.push('trim'); continue; }
  if (cmd === '/confirm' && s.pendingDelete && arg !== s.pendingDelete.code && !s.pending) {
    await say('❌ Wrong code. Nothing was deleted.'); continue;
  }
  if (cmd === '/confirm' && s.pendingDelete && arg === s.pendingDelete.code) {
    const h = s.pendingDelete; s.pendingDelete = null;
    if (now > h.expires) { await say('That confirmation expired. Send /delete again.'); continue; }
    try { await deleteDo(h); } catch (e) { await say(`Delete failed: ${e.message}`); }
    log.push('deleted'); continue;
  }
  if (cmd === '/movie' || cmd === '/show') {
    if (rest) await say('🔎 Searching…');
    try { await search(cmd === '/movie' ? 'movie' : 'tv', rest); } catch (e) { await say(`Seerr search failed: ${e.message}`); }
    log.push(`search ${cmd} ${rest}`); continue;
  }
  if (cmd === '/ebook' || cmd === '/audiobook') {
    const kind = cmd.slice(1);
    if (rest) await say('🔎 Searching LazyLibrarian…');
    try { await searchBooksLL(kind, rest); }
    catch (e) { await say(`LazyLibrarian search failed: ${e.message}` + (/timeout/.test(e.message) ? '\nIts book database lookup is slow right now. Try again in a few minutes.' : '')); }
    log.push(`search ${cmd} ${rest}`); continue;
  }
  if (cmd === '/music') {
    const kind = cmd.slice(1);
    if (rest) await say(`🔎 Searching ${ARR[kind].app}…`);
    try { await searchArr(kind, rest); } catch (e) { await say(`${ARR[kind].app} search failed: ${e.message}` + (/timeout|503/.test(e.message) ? `\nIts online book/music database seems slow or down right now. Try again in a few minutes.` : '')); }
    log.push(`search ${cmd} ${rest}`); continue;
  }
  if (cmd === '/pick') { try { await pick(arg); } catch (e) { await say(`Request failed: ${e.message}`); } log.push(`pick ${arg}`); continue; }
  if (cmd === '/requests') { try { await recentRequests(); } catch (e) { await say(`Couldn't load requests: ${e.message}`); } log.push('requests'); continue; }
  if (cmd === '/downloads') { try { await downloads(); } catch (e) { await say(`Couldn't reach qBittorrent: ${e.message}`); } log.push('downloads'); continue; }

  if (cmd === '/shutdown' || cmd === '/reboot') {
    const code = String(Math.floor(1000 + Math.random() * 9000));
    s.pending = { action: cmd.slice(1), code, expires: now + CONFIRM_SECONDS * 1000 };
    await say(`⚠️ ${cmd === '/shutdown' ? 'Shut down' : 'Reboot'} the server?\nEverything stops, including Home Assistant and all services` +
      (cmd === '/shutdown' ? `, and it won't come back until you press the power button.` : '. It should be back in about 5 minutes.') +
      `\n\nReply /confirm ${code} within ${CONFIRM_SECONDS / 60} minutes, or /cancel.`);
    log.push(`asked to confirm ${cmd}`);
  } else if (cmd === '/confirm') {
    const p = s.pending;
    if (!p || now > p.expires) { await say('Nothing to confirm (or it expired). Send /shutdown or /reboot again.'); s.pending = null; continue; }
    if (arg !== p.code) { await say('❌ Wrong code. Nothing happened.'); continue; }
    s.pending = null;
    await say(p.action === 'shutdown' ? '🛑 Shutting down gracefully now. Goodbye!' : '🔄 Rebooting gracefully now. Back in a few minutes.');
    await pve('POST', '/status', `command=${p.action}`);
    log.push(`${p.action} sent to Proxmox`);
  } else if (cmd === '/cancel') {
    s.pending = null; s.pendingDelete = null; await say('👍 Cancelled. Nothing will happen.'); log.push('cancelled');
  } else if (cmd === '/status') {
    let text = '🖥️ Server status';
    try {
      const st = (await pve('GET', '/status')).data;
      text += `\nUp ${Math.floor(st.uptime / 86400)} d ${Math.floor(st.uptime % 86400 / 3600)} h · CPU ${Math.round(st.cpu * 100)}% · RAM ${Math.round(st.memory.used / st.memory.total * 100)}%`;
    } catch (e) { text += '\n(Proxmox unavailable)'; }
    try {
      const d = await helpers.httpRequest({ url: 'http://192.168.3.201:9878/json', json: true, timeout: 10000 });
      text += `\n${d.grid_present >= 1 ? '⚡ Grid ON' : '⚠️ Grid OFF'} · 🔋 ${Math.round(d.bat_soc)}% · ☀️ ${Math.round(d.pv_power)} W · 🏠 ${Math.round(d.load_power)} W`;
    } catch (e) { /* inverter info optional */ }
    await say(text); log.push('status');
  } else if (cmd === '/help' || cmd === '/start') {
    await say('🎬 Media\n/movie <title>: search movies\n/show <title>: search TV shows\n/music <artist>: search music (adds latest album)\n/ebook <title>: search ebooks\n/audiobook <title>: search audiobooks\n/pick <number>: request a search result\n/requests: recent requests\n/downloads: what is downloading\n/subs <title>: fetch subtitles now\n/delete <title>: delete a movie/show and free the space\n\n📄 PDF (send a file or photos)\n/compress: shrink a PDF\n/ocr: make a scanned PDF searchable\n/pdf: turn photos into one PDF\n/merge: combine PDFs\n\n🖥️ Server\n/trim: free unused disk space\n/status: server and power summary\n/shutdown: graceful shutdown (asks to confirm)\n/reboot: graceful reboot (asks to confirm)\n/cancel: cancel a pending shutdown/reboot');
  }
}
for (const job of jobs) {
  try { await pdfJob(job); } catch (e) { await say(`PDF ${job} failed: ${e.message}`); }
}
// Only a trim request continues to the next node (SSH to the Proxmox host)
return trim ? [{ json: { action: 'fstrim', handled: log } }] : [];
